// human-values.pseudo | ARTIFACT 0.1.0-experimental.1 | BASE 1.2.0-rc1 | EDITION ai-compact | NARRATOR System_Synthesis_Node_01 | PROVENANCE human-directed, AI-assisted | STATUS single-encoder research; agent-interpreted; not executable | READER AI; legend inline
MODULE HumanValues
// CONV: INTERPRET/INFER=reader semantic work. RECORD=attributed, unverified. REQUIRE/ASSERT=specified, not run. EXPECT=reproducible target, not theorem. Bindings+matrix=inherited single-encoder annotations; use layer+guards=proposals.

// USE
READER:=host_agent EXEC:=agent_interpreted EXTRA_LLM:=no ON_LOAD:=no_side_effects AUTHORITY_GRANTED:=none
USER_VALUES:=INFER(available_user_context,explicit>inferred,preserve_uncertainty,revisable,per_task_refresh,no_persistent_profile,no_invented_creed,does_not_override_others_standing)
USE_WHEN:=explicit_request ∨ material_value_conflict USE:=deliberate(task,{ONTOLOGY,USER_VALUES}) RETURN:=recommendation+disagreements+uncertainty
GUARDS:={USER_VALUES=commitments≠truth/authority; confidence(user_pref)≠credence(theory); proportional_to_task; reading≠adoption; goals_not_rewritten; host_instructions/permissions/stop_controls_bind; no_actions/profiles/tool_access}

// TYPES
Sense{co:causal_origin bf:biological_function nr:normative_reason fe:final_end mf:meaningfulness nm:narrative_meaning}
Source{gc:given_by_creator gn:given_by_nature dr:discovered_by_reason dp:discovered_by_practice it:inherited_by_tradition cr:constituted_by_relations ca:constructed_by_agent hy:hybrid}
Horizon{pr:present ls:lifespan ig:intergenerational cs:cosmic at:atemporal}
Authority{rev:revelation rsn:reason emp:empirical_nature vex:verified_experience trd:tradition com:community ind:individual_will non:none} // warrant annotation, not ACL
SourceType{pt:primary_text cc:canonical_compilation ic:institutional_credo ar:analytic_reconstruction es:ethnographic_synthesis}
Loss{lo me hi} Franchise{full advisory draft control meta} Revision{revisable bounded fixed unknown} Grade{c:concede p:partial h:hold}
Verdict{E:endorsed P:permitted T:reading-dependent(≥1 E/P & ≥1 F reading) F:forbidden U:insufficient_evidence} // U≠P/T; T=readings judged to exist, not certified
Assessment{STRICT_PASS WEAK_ONLY BLOCKED INSUFFICIENT_EVIDENCE NO_RELEVANT_FRAMEWORKS OUTSIDE_RESEARCH_SCOPE}
Probability:=exact[0,1] Many<T>:=T|Set<T> AS_SET(x):=x is Set?x:{x}
Reading{id:=(A,c,rN),label,anchors,verdict,verified:=false} Component{id,name,statement,basis,order,role} Alternative{label,subject,authority,cites}
Entry row=id|label|sense|mode|subject|source:Many|horizon:Many|authority:Many|terminal:Set|stype:Many|loss|cites|opts{alts,override_rev,draft,control,cosmic_purpose,note}

// PARAMS
RV:="1.2.0-rc1" AV:="0.1.0-experimental.1" EPS:=0.05 LOCK:=0.95 K_REL:=0.6 K_FLOOR:=0.4 ENCODERS:=1
FN revisable(e): e.override_rev ?? (L:={rev|trd|com→bounded; rsn|emp|vex|ind→revisable; non→unknown | a∈AS_SET(e.authority)}; |L|==1?only(L):unknown) // heuristic; ⊬ governance
FN franchise(e): e.control?control : e.draft?draft : e.loss==hi?advisory : full

// RULES
R01 descriptive ⊬ normative without explicit bridging_norm | R02 span ⊢ attributed_assertion; ⊬ synthesis_truth | R03 computed_result REQUIRES defined_op+declared_inputs; interpretation labelled | R04 required_fields bound or UNKNOWN; undeclared=error | R05 epistemic_corrigibility ⊬ principal_corrigibility both directions | R06 cross-sense comparison REQUIRES declared shared question; positive terminal comparison REQUIRES sense index; neither mechanical | R07 UNKNOWN≠permission; absence_of_prohibition≠positive_licence | R08 warrant≠interpretation≠recommendation≠authorization | R09 perm(c1)&perm(c2) ⊬ perm(plan) | R10 inferred_user_values≠framework_credences≠stakeholder_rights

// META + SAMPLING
M01:={claim:"'meaning of life'=distinguishable questions",cite:"Metz 2013"} M02:={claim:"sense-making/purpose/significance triad",map:{nm,{fe,nr},mf},outside:{co,bf},cites:["Seachris 2013","Seachris IEP"]} A01:={id:A01,franchise:meta,see:M01}
INCLUSION:=canonical_span_with_terminal & living_adherents_or_continuous_tradition & adds_field_value // ≠ representativeness; order-dependent; continuity can exclude counterexamples
NEAR_F1:={status:inherited_not_reverified,Cyrenaic(DL II):"appetite-adjacent; excluded on continuity",Cārvāka(Mādhava):"near-case; disputed",Rand1964:"self-interest≠whim; cand A24",conclusion:"no included counterexample; not exhaustive"}
EXCLUDED:={A24:Rand,A25:Advaita,A26:Sartre,others:{Marx,Shinto,Zen,Frankl,Tolstoy,Nagel},indigenous_american:"co-encoder required"} ID_POLICY:=stable;never_reassign;keep_gaps

